/* Famili'Quiz — Sciences */
QUIZ_DATA.add('sciences', [
  // ===== Niveau 1 : 7-9 ans =====
  { l: 1, q: "Comment appelle-t-on les premières dents d’un enfant ?", a: ["Les dents de lait", "Les dents de sagesse", "Les dents de fer"], e: "😁👶", f: "Un enfant a 20 dents de lait. Elles commencent à tomber vers 6 ans pour laisser place aux dents définitives." },
  { l: 1, q: "Quel organe pompe le sang dans tout le corps ?", a: ["Le cœur", "Les poumons", "L’estomac", "Le foie"], e: "🩸🏃", f: "Ton cœur bat environ 100 000 fois par jour, sans jamais prendre de vacances !" },
  { l: 1, q: "Avec quels organes respire-t-on ?", a: ["Les poumons", "Les reins", "Les intestins", "Les muscles"], e: "🌬️🎈", f: "Nous avons deux poumons. Le gauche est un peu plus petit, pour laisser de la place au cœur." },
  { l: 1, q: "Avec quel sens sent-on l’odeur d’un gâteau ?", a: ["L’odorat", "L’ouïe", "Le toucher", "La vue"], e: "🎂😊", f: "Ton nez peut reconnaître des milliers d’odeurs. Sans odorat, les aliments ont beaucoup moins de goût !" },
  { l: 1, q: "Que faut-il faire avant de passer à table ?", a: ["Se laver les mains", "Se couper les ongles", "Se brosser les cheveux"], e: "🍽️🦠", f: "Se frotter les mains avec du savon pendant 30 secondes chasse la plupart des microbes." },
  { l: 1, q: "Qu’est-ce qui fait des trous (des caries) dans les dents ?", a: ["Les microbes et le sucre", "L’eau du robinet", "Le dentifrice"], e: "🍬😬", f: "Les microbes de la bouche transforment le sucre en acide. Cet acide attaque les dents et fait des trous." },
  { l: 1, q: "Comment appelle-t-on les restes de dinosaures devenus de la pierre ?", a: ["Des fossiles", "Des cristaux", "Des diamants"], e: "🦕⛏️", f: "Un fossile met des millions d’années à se former : les os sont remplacés petit à petit par des minéraux." },
  { l: 1, q: "Quel dinosaure géant avait de tout petits bras ?", a: ["Le tyrannosaure", "Le diplodocus", "Le tricératops", "Le stégosaure"], e: "🦴💪", f: "Les bras du T. rex mesuraient environ 1 mètre : c’est tout petit pour un animal de 12 mètres de long !" },
  { l: 1, q: "Quel dinosaure avait trois cornes sur la tête ?", a: ["Le tricératops", "Le vélociraptor", "Le brachiosaure"], e: "🦕🤔", f: "« Tricératops » veut dire « visage à trois cornes » en grec." },
  { l: 1, q: "Que mangeait le diplodocus ?", a: ["Des plantes", "De la viande", "Des poissons", "Des insectes"], e: "🦕🍽️", f: "Le diplodocus mesurait environ 25 mètres de long, plus que deux bus mis bout à bout !" },
  { l: 1, q: "Comment appelle-t-on le scientifique qui étudie les dinosaures ?", a: ["Un paléontologue", "Un dentiste", "Un astronaute", "Un pharmacien"], e: "🦕🔍", f: "Les paléontologues dégagent les fossiles avec des pinceaux et de petits outils pour ne rien casser." },
  { l: 1, q: "Quelle partie du squelette protège notre cerveau ?", a: ["Le crâne", "La rotule", "Le bassin"], e: "🧠🛡️", f: "Chez le bébé, les os du crâne ne sont pas encore soudés : on sent des zones plus molles, appelées fontanelles." },
  { l: 1, q: "En quoi se transforme l’eau quand on la chauffe très fort ?", a: ["En vapeur", "En glace", "En sable"], e: "🍲🔥", f: "La vapeur d’eau est invisible ! Le petit nuage blanc au-dessus de la casserole, ce sont de minuscules gouttes." },
  { l: 1, q: "Que devient l’eau quand on la met au congélateur ?", a: ["De la glace", "De la vapeur", "Du lait"], e: "💧🥶", f: "L’eau pure gèle à 0 °C. Dans un congélateur, il fait souvent −18 °C !" },
  { l: 1, q: "Que se passe-t-il quand on mélange bien du sucre dans de l’eau ?", a: ["Il se dissout", "Il explose", "Il devient du sel"], e: "🥄💧", f: "Le sucre n’a pas disparu : il est toujours là ! Goûte l’eau, elle est sucrée." },
  { l: 1, q: "Le jus d’orange, c’est un solide, un liquide ou un gaz ?", a: ["Un liquide", "Un solide", "Un gaz"], e: "🍊🥤", f: "Un liquide prend la forme du récipient dans lequel on le verse : verre, bol ou bouteille !" },
  { l: 1, q: "Que met-on souvent dans une lampe de poche pour qu’elle marche ?", a: ["Des piles", "Des billes", "Du sable", "Des graines"], e: "🔦❓", f: "La première pile électrique a été inventée par l’Italien Alessandro Volta, en 1800." },
  { l: 1, q: "Que fait un aimant quand on l’approche d’un trombone en fer ?", a: ["Il l’attire", "Il le fait fondre", "Il le rend invisible"], e: "🧲📎", f: "Les aimants attirent le fer, mais pas le plastique, le bois ni le papier." },
  { l: 1, q: "Quand on frotte un ballon sur ses cheveux, que font les cheveux ?", a: ["Ils se dressent vers le ballon", "Ils deviennent bleus", "Ils tombent tous"], e: "🎈💇", f: "C’est l’électricité statique : en frottant, le ballon se charge et attire les cheveux." },
  { l: 1, q: "Grâce à quel sens entend-on les sons ?", a: ["L’ouïe", "L’odorat", "Le toucher", "La vue"], e: "🎶🔔", f: "Nos oreilles nous servent aussi à garder l’équilibre, grâce à de petits canaux remplis de liquide." },
  { l: 1, q: "Que se forme-t-il quand un objet bloque la lumière ?", a: ["Une ombre", "Un arc-en-ciel", "Un reflet", "Un éclair"], e: "🔦🖐️", f: "Avec tes mains devant une lampe, tu peux faire des ombres chinoises en forme d’animaux !" },
  { l: 1, q: "À quoi sert une loupe ?", a: ["À voir les choses en plus grand", "À entendre de plus loin", "À peser les objets"], e: "🐜🔍", f: "Une loupe est une lentille plus épaisse au milieu que sur les bords." },
  { l: 1, q: "Avec quoi le médecin écoute-t-il ton cœur ?", a: ["Un stéthoscope", "Un thermomètre", "Un microscope", "Un télescope"], e: "👩‍⚕️❤️", f: "Le stéthoscope a été inventé en France par le médecin René Laennec, en 1816." },
  { l: 1, q: "Avec quel instrument pèse-t-on des pommes ?", a: ["Une balance", "Une règle", "Un thermomètre", "Une boussole"], e: "🍎🍏", f: "On mesure les masses en grammes et en kilogrammes. Un litre d’eau pèse environ 1 kilo !" },
  { l: 1, q: "Combien y a-t-il de minutes dans une heure ?", a: ["60", "100", "30", "24"], e: "⏰⌛", f: "On doit ce compte par 60 aux Babyloniens, de très anciens savants de Mésopotamie." },
  { l: 1, q: "Combien y a-t-il de centimètres dans un mètre ?", a: ["100", "10", "1 000"], e: "📏🤔", f: "« Centi » veut dire « centième » : un centimètre, c’est un centième de mètre !" },
  { l: 1, q: "Combien de côtés a un triangle ?", a: ["3", "4", "5", "6"], e: "✏️📏", f: "« Triangle » veut dire « trois angles ». Les panneaux qui signalent un danger sur la route ont cette forme !" },
  { l: 1, q: "Combien as-tu de doigts en tout, aux mains et aux pieds ?", a: ["20", "10", "15", "25"], e: "🖐️🦶", f: "Les Mayas comptaient par paquets de 20, peut-être en s’aidant des doigts et des orteils !" },
  { l: 1, q: "Comment s’appelle la forme qui a 4 côtés égaux et 4 angles droits ?", a: ["Le carré", "Le cercle", "Le triangle", "L’ovale"], e: "📐✏️", f: "Le carré est un rectangle très spécial : ses 4 côtés ont la même longueur !" },
  { l: 1, q: "Tu as 3 bonbons et on t’en donne 4. Combien en as-tu ?", a: ["7", "6", "8", "12"], e: "🍬😋", f: "Additionner, c’est rassembler. Et 3 + 4, c’est pareil que 4 + 3 !" },
  { l: 1, q: "Quel appareil permet de parler avec quelqu’un qui est très loin ?", a: ["Le téléphone", "Le réfrigérateur", "L’aspirateur"], e: "🗣️🌍", f: "Le téléphone a été breveté en 1876 par Alexander Graham Bell." },
  { l: 1, q: "Comment appelle-t-on une machine qui peut bouger et travailler toute seule ?", a: ["Un robot", "Un marteau", "Un vélo"], e: "⚙️🔋", f: "Le mot « robot » vient du tchèque « robota », qui veut dire « corvée » ou « travail forcé »." },
  { l: 1, q: "Avec quoi déplace-t-on la petite flèche sur l’écran d’un ordinateur ?", a: ["La souris", "L’imprimante", "Le haut-parleur", "La webcam"], e: "💻👆", f: "On l’appelle « souris » parce qu’avec son fil, elle ressemblait à une petite souris avec sa queue !" },
  { l: 1, q: "Qu’est-ce qui fait tourner les pales des éoliennes ?", a: ["Le vent", "La pluie", "La lune"], e: "⚡🔄", f: "En tournant, les éoliennes fabriquent de l’électricité. Leurs pales peuvent être plus longues qu’un terrain de tennis !" },
  { l: 1, q: "De quelle couleur est notre sang ?", a: ["Rouge", "Bleu", "Vert", "Jaune"], e: "🩹🧒", f: "Le sang est toujours rouge ! Les veines paraissent bleues seulement à cause de la peau et de la lumière." },
  { l: 1, q: "Qu’est-ce qui permet à nos os de bouger ?", a: ["Les muscles", "Les cheveux", "Les ongles"], e: "🤸🦴", f: "Le plus gros muscle du corps se trouve… dans les fesses : c’est le grand fessier !" },
  { l: 1, q: "Quel organe nous sert à penser ?", a: ["Le cerveau", "Le cœur", "L’estomac", "Le genou"], e: "🤔💭", f: "Ton cerveau travaille même la nuit : c’est lui qui fabrique tes rêves !" },
  { l: 1, q: "Quand on tape sur un tambour, que fait la peau du tambour ?", a: ["Elle vibre", "Elle fond", "Elle brille", "Elle gonfle"], e: "🥁👂", f: "Tous les sons sont des vibrations ! Pose la main sur ta gorge quand tu parles : tu la sens vibrer." },
  { l: 1, q: "Dans quoi vaut-il mieux éternuer quand on n’a pas de mouchoir ?", a: ["Dans son coude", "Dans son assiette", "Vers les copains"], e: "🤧🦠", f: "Un éternuement peut projeter des gouttelettes à plusieurs mètres. Le coude les arrête !" },
  { l: 1, q: "Lequel de ces objets flotte sur l’eau ?", a: ["Un bouchon de liège", "Un caillou", "Une clé en métal", "Une bille en verre"], e: "🛁💧", f: "Le liège est rempli de minuscules bulles d’air : c’est pour ça qu’il est si léger !" },
  { l: 1, q: "Pourquoi une pomme tombe-t-elle quand on la lâche ?", a: ["La Terre l’attire", "Le vent la pousse", "Elle est fatiguée"], e: "🍎👇", f: "C’est la gravité : la Terre attire tout vers elle, les pommes, les ballons… et toi aussi !" },
  { l: 1, q: "Sur quel sol glisse-t-on le plus facilement ?", a: ["La glace", "Le tapis", "L’herbe", "Le sable"], e: "👟😮", f: "Moins il y a de frottements, plus on glisse : c’est pour ça qu’on patine sur la glace et pas sur le sable !" },
  { l: 1, q: "Que se passe-t-il quand on mélange du vinaigre et du bicarbonate ?", a: ["Ça mousse et fait des bulles", "Ça gèle d’un coup", "Ça devient tout noir"], e: "🧪🥄", f: "Les bulles sont du dioxyde de carbone, le même gaz que dans les boissons pétillantes !" },
  { l: 1, q: "Quelle partie du corps nous sert à goûter les aliments ?", a: ["La langue", "Les oreilles", "Les dents", "Les cheveux"], e: "🍭🍋", f: "Les cellules du goût de ta langue sont remplacées environ tous les 10 jours !" },
  { l: 1, q: "Pourquoi ça ne fait pas mal de se couper les ongles ?", a: ["Le bout de l’ongle n’a pas de nerfs", "Les ongles sont en plastique", "Les ongles sont endormis"], e: "💅✂️", f: "Les ongles sont faits de kératine, comme les cheveux… et la corne des rhinocéros !" },
  { l: 1, q: "De quoi notre corps est-il surtout composé ?", a: ["D’eau", "De sable", "De sucre", "De fer"], e: "🧍❓", f: "Le corps d’un adulte contient environ 60 % d’eau. Celui d’un bébé, encore plus !" },
  { l: 1, q: "Quel organe en forme de poche reçoit les aliments que l’on avale ?", a: ["L’estomac", "Les poumons", "Le cœur"], e: "🍽️😋", f: "L’estomac fabrique un suc très acide qui aide à digérer les aliments. Il peut s’étirer pour contenir un gros repas !" },
  { l: 1, q: "Lequel de ces nombres est pair ?", a: ["8", "3", "5", "7"], e: "🔢🤔", f: "Un nombre pair peut se partager en deux parts égales. Il se termine toujours par 0, 2, 4, 6 ou 8." },
  { l: 1, q: "Pourquoi met-on de la crème solaire en plein soleil ?", a: ["Pour protéger sa peau", "Pour sentir bon", "Pour avoir moins chaud"], e: "☀️🏖️", f: "Même quand il y a des nuages, une partie des rayons du soleil qui brûlent la peau passe à travers !" },
  { l: 1, q: "Pourquoi transpire-t-on quand on a très chaud ?", a: ["Pour rafraîchir le corps", "Pour se laver", "Pour boire moins"], e: "🥵🏃", f: "En s’évaporant sur la peau, la sueur emporte de la chaleur : c’est notre climatisation naturelle !" },

  // ===== Niveau 2 : 10-12 ans =====
  { l: 2, q: "Combien d’os compte le squelette d’un adulte ?", a: ["206", "106", "306", "56"], e: "🦴🧍", f: "Plus de la moitié de nos os se trouvent dans les mains et les pieds !" },
  { l: 2, q: "Quel est le plus petit os du corps humain ?", a: ["L’étrier", "La rotule", "Le coccyx", "L’omoplate"], e: "🦴🔍", f: "L’étrier se cache dans l’oreille et mesure environ 3 millimètres : plus petit qu’un grain de riz !" },
  { l: 2, q: "Quel est le plus grand organe du corps humain ?", a: ["La peau", "Le foie", "Les poumons", "L’intestin"], e: "🧍🔍", f: "Étalée, la peau d’un adulte couvrirait près de 2 m², et elle pèse plusieurs kilos !" },
  { l: 2, q: "Quelles cellules du sang combattent les microbes ?", a: ["Les globules blancs", "Les globules rouges", "Les plaquettes"], e: "🦠🛡️", f: "Quand tu es malade, ton corps produit davantage de globules blancs pour se défendre." },
  { l: 2, q: "Quel gaz, fabriqué par notre corps, rejetons-nous en expirant ?", a: ["Le dioxyde de carbone", "L’oxygène", "L’hélium", "Le néon"], e: "🌬️😮", f: "L’air que l’on expire contient environ 100 fois plus de dioxyde de carbone que l’air que l’on inspire." },
  { l: 2, q: "Quelle est la partie la plus dure du corps humain ?", a: ["L’émail des dents", "Le fémur", "Le crâne", "Les ongles"], e: "💎🧍", f: "L’émail est la matière la plus dure du corps, mais il ne repousse pas : d’où l’importance du brossage !" },
  { l: 2, q: "Quel organe filtre le sang pour fabriquer l’urine ?", a: ["Le rein", "Le foie", "Le cœur", "La rate"], e: "🩸🚽", f: "Chaque jour, nos deux reins filtrent environ 180 litres de liquide sanguin… mais on n’urine qu’environ 1,5 litre !" },
  { l: 2, q: "À quoi sert un vaccin ?", a: ["À apprendre au corps à se défendre", "À réparer un os cassé", "À faire grandir plus vite"], e: "💉🛡️", f: "Le premier vaccin, contre la variole, a été mis au point par le médecin anglais Edward Jenner en 1796." },
  { l: 2, q: "Contre quoi les antibiotiques sont-ils efficaces ?", a: ["Les bactéries", "Les virus", "Les allergies", "Les fractures"], e: "💊🦠", f: "Les antibiotiques ne servent à rien contre les virus, comme ceux du rhume ou de la grippe." },
  { l: 2, q: "Selon les scientifiques, quels animaux actuels descendent des dinosaures ?", a: ["Les oiseaux", "Les crocodiles", "Les tortues"], e: "🦖🔍", f: "Pour beaucoup de scientifiques, les oiseaux sont même des dinosaures… encore vivants !" },
  { l: 2, q: "Il y a combien de temps les derniers dinosaures géants ont-ils disparu ?", a: ["66 millions d’années", "6 600 ans", "660 000 ans", "6 milliards d’années"], e: "🦕☄️", f: "Selon la plupart des scientifiques, la chute d’un astéroïde géant au Mexique en est la principale cause." },
  { l: 2, q: "D’après les fossiles, qu’avait le vrai vélociraptor sur le corps ?", a: ["Des plumes", "Une carapace", "De la fourrure", "Des écailles de poisson"], e: "🦖🎬", f: "Le vrai vélociraptor avait à peu près la taille d’un dindon, bien plus petit que dans les films !" },
  { l: 2, q: "À quelle température l’eau pure bout-elle au niveau de la mer ?", a: ["100 °C", "50 °C", "200 °C"], e: "🍲🌡️", f: "En montagne, l’eau bout plus tôt : vers 85 °C au sommet du mont Blanc !" },
  { l: 2, q: "Comment appelle-t-on le passage de l’état liquide à l’état gazeux ?", a: ["La vaporisation", "La fusion", "La solidification", "La condensation"], e: "💧➡️", f: "L’évaporation se fait doucement, même sans chauffer ; l’ébullition, c’est quand le liquide bout !" },
  { l: 2, q: "Pourquoi de la buée apparaît-elle sur le miroir de la salle de bain ?", a: ["La vapeur d’eau s’y refroidit", "Le verre fabrique de l’eau", "Le savon colle au miroir"], e: "🚿🛁", f: "C’est la condensation, l’inverse de l’évaporation. C’est aussi pour ça qu’une canette fraîche se couvre de gouttes !" },
  { l: 2, q: "Quelle est la formule chimique de l’eau ?", a: ["H₂O", "CO₂", "O₂", "NaCl"], e: "💧🧪", f: "Une molécule d’eau, c’est 2 atomes d’hydrogène accrochés à 1 atome d’oxygène." },
  { l: 2, q: "Quel métal trouve-t-on dans la plupart des fils électriques de la maison ?", a: ["Le cuivre", "L’or", "Le fer", "Le plomb"], e: "🔌⚡", f: "Le cuivre conduit très bien l’électricité. Seul l’argent fait mieux, mais il coûte beaucoup plus cher !" },
  { l: 2, q: "Lequel de ces matériaux ne conduit pas l’électricité ?", a: ["Le plastique", "Le cuivre", "L’aluminium", "Le fer"], e: "🔌🤔", f: "C’est pour ça que les fils électriques sont entourés de plastique : c’est un isolant qui nous protège." },
  { l: 2, q: "Que se passe-t-il si on approche les pôles nord de deux aimants ?", a: ["Ils se repoussent", "Ils s’attirent", "Ils s’éteignent"], e: "🧲🧲", f: "Deux pôles identiques se repoussent ; un pôle nord et un pôle sud s’attirent." },
  { l: 2, q: "Grâce à quoi l’aiguille d’une boussole indique-t-elle le nord ?", a: ["Le magnétisme de la Terre", "La lumière du Soleil", "La force du vent", "La rotation de l’aiguille"], e: "🧭🗺️", f: "La Terre se comporte comme un aimant géant, grâce au fer liquide qui bouge dans son noyau." },
  { l: 2, q: "Lequel de ces trois va le plus vite ?", a: ["La lumière", "Le son", "Un avion supersonique"], e: "⚡🏁", f: "Dans l’air, la lumière va presque un million de fois plus vite que le son !" },
  { l: 2, q: "Que devient la lumière blanche quand elle traverse un prisme ?", a: ["Elle se sépare en couleurs", "Elle devient noire", "Elle disparaît", "Elle devient chaude"], e: "🔦💎", f: "Vers 1666, Isaac Newton a montré que la lumière blanche est un mélange de toutes les couleurs." },
  { l: 2, q: "Comment s’appelle un son qui revient après avoir rebondi sur une paroi ?", a: ["L’écho", "Le larsen", "L’ultrason", "Le bruit blanc"], e: "🏔️🗣️", f: "Les sonars des bateaux envoient des sons sous l’eau et écoutent leur écho pour mesurer la profondeur." },
  { l: 2, q: "Pourquoi les pneus de voiture ont-ils des rainures ?", a: ["Pour évacuer l’eau et mieux adhérer", "Pour faire moins de bruit", "Pour être plus légers"], e: "🚗🌧️", f: "Sans rainures, une voiture risque l’aquaplaning : elle glisse sur une fine couche d’eau." },
  { l: 2, q: "Pourquoi un parachute ralentit-il la chute ?", a: ["L’air freine sa grande toile", "Il est plus léger que l’air", "Il annule la gravité"], e: "🪂☁️", f: "Plus la surface est grande, plus l’air résiste : c’est la résistance de l’air." },
  { l: 2, q: "Quel gaz représente presque 80 % de l’air que nous respirons ?", a: ["L’azote", "L’oxygène", "Le dioxyde de carbone", "L’hydrogène"], e: "🌬️🧪", f: "L’oxygène, lui, ne représente qu’environ 21 % de l’air." },
  { l: 2, q: "Que se forme-t-il sur un objet en fer laissé longtemps sous la pluie ?", a: ["De la rouille", "Du vert-de-gris", "Du calcaire", "Du sel"], e: "🔩🌧️", f: "La rouille naît d’une réaction entre le fer, l’oxygène de l’air et l’eau." },
  { l: 2, q: "Pour faire du feu, il faut un combustible, de la chaleur et… quoi d’autre ?", a: ["De l’oxygène", "De l’azote", "De l’eau", "Du sable"], e: "🔥🏕️", f: "C’est le « triangle du feu » : il suffit d’en retirer un côté pour éteindre l’incendie." },
  { l: 2, q: "Le jus de citron est-il acide, basique ou neutre ?", a: ["Acide", "Basique", "Neutre"], e: "🍋🧪", f: "Le citron contient de l’acide citrique, qui lui donne son goût piquant… et qui dissout même le calcaire !" },
  { l: 2, q: "Combien font les trois angles d’un triangle additionnés ?", a: ["180°", "90°", "360°", "270°"], e: "📐🔺", f: "C’est vrai pour tous les triangles dessinés sur une surface plane, des tout petits aux géants !" },
  { l: 2, q: "Comment s’appelle un polygone à 6 côtés ?", a: ["Un hexagone", "Un pentagone", "Un octogone", "Un heptagone"], e: "📐🤔", f: "Les alvéoles des abeilles sont des hexagones : la forme qui utilise le moins de cire pour ranger le plus de miel !" },
  { l: 2, q: "Combien font 12 × 12 ?", a: ["144", "124", "142", "122"], e: "✖️🧠", f: "Douze douzaines, cela s’appelle une « grosse » : 144 objets !" },
  { l: 2, q: "Combien y a-t-il de secondes dans une heure ?", a: ["3 600", "360", "6 000", "1 000"], e: "⏱️🧮", f: "60 secondes × 60 minutes = 3 600 secondes. Et dans une journée : 86 400 secondes !" },
  { l: 2, q: "Combien y a-t-il de grammes dans un kilogramme ?", a: ["1 000", "100", "10"], e: "⚖️🍎", f: "« Kilo » vient d’un mot grec qui veut dire « mille »." },
  { l: 2, q: "En France, en quelle unité mesure-t-on la température au quotidien ?", a: ["Le degré Celsius", "Le degré Fahrenheit", "Le kelvin"], e: "🌡️☀️", f: "Aux États-Unis, on utilise les degrés Fahrenheit : 100 °F, c’est environ 38 °C !" },
  { l: 2, q: "Quel est l’os le plus long du corps humain ?", a: ["Le fémur", "Le tibia", "L’humérus", "Le radius"], e: "🦴📏", f: "Le fémur est l’os de la cuisse. Il mesure environ le quart de la taille d’une personne." },
  { l: 2, q: "Comment appelle-t-on un angle qui mesure exactement 90° ?", a: ["Un angle droit", "Un angle plat", "Un angle aigu", "Un angle obtus"], e: "📏✏️", f: "Un angle aigu mesure moins de 90°, un angle obtus entre 90° et 180°, et un angle plat exactement 180°." },
  { l: 2, q: "Comment s’appellent les vaisseaux qui ramènent le sang vers le cœur ?", a: ["Les veines", "Les artères", "Les nerfs", "Les tendons"], e: "🩸❤️", f: "Les artères, elles, emportent le sang du cœur vers le reste du corps. Dans les jambes, de petites valves empêchent le sang de redescendre." },
  { l: 2, q: "Quel savant est célèbre pour la formule E = mc² ?", a: ["Albert Einstein", "Isaac Newton", "Marie Curie", "Galilée"], e: "🧠💡", f: "Einstein a reçu le prix Nobel de physique… mais pas pour la relativité : pour ses travaux sur la lumière !" },
  { l: 2, q: "Comment s’appelle le « cerveau » de l’ordinateur, qui fait les calculs ?", a: ["Le processeur", "Le disque dur", "L’écran", "La carte son"], e: "💻🧠", f: "Un processeur moderne peut réaliser des milliards d’opérations chaque seconde !" },
  { l: 2, q: "Avec quels chiffres un ordinateur code-t-il toutes ses informations ?", a: ["0 et 1", "1 et 2", "0 à 9"], e: "💻🔢", f: "C’est le système binaire : chaque 0 ou 1 s’appelle un « bit »." },
  { l: 2, q: "Que signifie l’abréviation « IA » ?", a: ["Intelligence artificielle", "Internet avancé", "Image animée", "Information automatique"], e: "🤖💬", f: "L’expression « intelligence artificielle » a été popularisée en 1956, lors d’une conférence aux États-Unis." },
  { l: 2, q: "Lequel de ces moyens de produire de l’électricité est renouvelable ?", a: ["Un barrage hydroélectrique", "Une centrale au charbon", "Une centrale au gaz", "Une centrale au fioul"], e: "⚡♻️", f: "Un barrage utilise la force de l’eau qui descend pour faire tourner des turbines." },
  { l: 2, q: "Quel appareil transforme la lumière du soleil en électricité ?", a: ["Le panneau photovoltaïque", "L’éolienne", "La dynamo", "Le radiateur"], e: "☀️🏠", f: "« Photo » vient du grec et veut dire « lumière » ; « volt » vient du nom du savant italien Volta." },
  { l: 2, q: "Comment appelle-t-on la plus petite unité vivante de notre corps ?", a: ["La cellule", "L’atome", "L’organe", "Le muscle"], e: "🔬🧍", f: "Notre corps contient des dizaines de milliers de milliards de cellules !" },
  { l: 2, q: "Quelle est la température normale du corps humain ?", a: ["Environ 37 °C", "Environ 30 °C", "Environ 40 °C", "Environ 25 °C"], e: "🧍🌡️", f: "Au-dessus de 38 °C, on parle de fièvre : le corps se réchauffe pour mieux combattre les microbes." },
  { l: 2, q: "Comment s’appelle le rond noir au centre de l’œil ?", a: ["La pupille", "L’iris", "La rétine", "La cornée"], e: "👁️🔦", f: "La pupille est en fait un trou : elle s’agrandit dans le noir pour laisser entrer plus de lumière." },
  { l: 2, q: "Combien de cavités (ou « chambres ») compte le cœur humain ?", a: ["4", "2", "3", "6"], e: "❤️🔍", f: "Deux oreillettes en haut, deux ventricules en bas : le cœur est une double pompe !" },
  { l: 2, q: "Lequel de ces nombres est divisible par 3 ?", a: ["51", "52", "53", "55"], e: "➗🤔", f: "Astuce : un nombre est divisible par 3 si la somme de ses chiffres l’est. Ici, 5 + 1 = 6 !" },
  { l: 2, q: "Combien d’arêtes possède un cube ?", a: ["12", "6", "8", "24"], e: "🎁📐", f: "Un cube a 6 faces, 8 sommets et 12 arêtes. Et 6 + 8 − 12 = 2, comme pour tous les polyèdres convexes !" },

  // ===== Niveau 3 : 13-16 ans =====
  { l: 3, q: "Combien de chromosomes contient une cellule humaine ordinaire (non sexuelle) ?", a: ["46", "23", "48", "64"], e: "🧬🧍", f: "Ils vont par paires : 23 viennent de la mère et 23 du père. Le chimpanzé, lui, en a 48 !" },
  { l: 3, q: "Quelle forme a la molécule d’ADN ?", a: ["Une double hélice", "Une sphère creuse", "Un simple anneau", "Une pyramide"], e: "🔬🧪", f: "Sa structure a été décrite en 1953 par Watson et Crick, grâce notamment aux images de Rosalind Franklin." },
  { l: 3, q: "Quelle partie de la cellule produit l’essentiel de son énergie ?", a: ["La mitochondrie", "Le noyau", "Le ribosome", "L’appareil de Golgi"], e: "🔋🔬", f: "Les mitochondries ont leur propre ADN, qui est presque toujours transmis par la mère." },
  { l: 3, q: "Quel est le rôle principal des globules rouges ?", a: ["Transporter l’oxygène", "Combattre les microbes", "Faire coaguler le sang", "Digérer les graisses"], e: "🩸🏃", f: "Leur couleur vient de l’hémoglobine, une protéine qui contient du fer et qui capte l’oxygène." },
  { l: 3, q: "Quel organe fabrique l’insuline ?", a: ["Le pancréas", "Le foie", "La rate", "La thyroïde"], e: "🍬💉", f: "L’insuline fait baisser le taux de sucre dans le sang. Dans le diabète de type 1, le corps n’en produit plus." },
  { l: 3, q: "Comment s’appellent les cellules qui transmettent les messages nerveux ?", a: ["Les neurones", "Les globules", "Les hépatocytes", "Les kératinocytes"], e: "🧠⚡", f: "Le cerveau humain contient environ 86 milliards de neurones !" },
  { l: 3, q: "La « carte des goûts » de la langue (sucré au bout, amer au fond…), c’est…", a: ["Une idée reçue fausse", "Un fait prouvé", "Vrai seulement chez l’enfant", "Vrai seulement pour le sucré"], e: "👅🗺️", f: "Chaque bourgeon du goût, où qu’il soit sur la langue, peut détecter toutes les saveurs de base." },
  { l: 3, q: "Sur quelle partie de l’œil l’image se forme-t-elle ?", a: ["La rétine", "La cornée", "Le cristallin", "L’iris"], e: "👁️📷", f: "L’image s’y forme à l’envers : c’est le cerveau qui la remet à l’endroit !" },
  { l: 3, q: "Quelle est, environ, la plage de fréquences audible par une oreille humaine jeune ?", a: ["De 20 Hz à 20 000 Hz", "De 2 Hz à 200 Hz", "De 1 000 Hz à 5 000 Hz", "De 200 Hz à 2 millions de Hz"], e: "👂🎵", f: "Avec l’âge, on perd surtout les sons aigus : certaines sonneries très aiguës ne sont entendues que par les jeunes !" },
  { l: 3, q: "Quelle unité utilise-t-on pour mesurer le niveau sonore ?", a: ["Le décibel", "Le hertz", "Le lux", "Le newton"], e: "🔊📏", f: "Au-delà d’environ 85 décibels, une exposition prolongée peut abîmer l’audition." },
  { l: 3, q: "Quelle est, environ, la vitesse de la lumière dans le vide ?", a: ["300 000 km/s", "300 km/s", "30 000 km/h", "3 millions de km/s"], e: "💡🏎️", f: "En une seconde, la lumière pourrait faire plus de 7 fois le tour de la Terre !" },
  { l: 3, q: "Pourquoi une tomate nous paraît-elle rouge à la lumière du jour ?", a: ["Elle renvoie surtout le rouge", "Elle absorbe le rouge", "Elle produit sa propre lumière", "Elle est plus chaude"], e: "🍅👀", f: "Les autres couleurs de la lumière blanche sont absorbées. Éclairée en lumière bleue, elle paraîtrait presque noire !" },
  { l: 3, q: "Quelles sont les trois couleurs primaires de la lumière, utilisées par les écrans ?", a: ["Rouge, vert, bleu", "Rouge, jaune, bleu", "Cyan, magenta, jaune", "Noir, blanc, gris"], e: "📺🔦", f: "En superposant de la lumière rouge, verte et bleue, on obtient du blanc : c’est la synthèse additive." },
  { l: 3, q: "Pourquoi une paille semble-t-elle cassée dans un verre d’eau ?", a: ["La lumière change de direction", "L’eau plie la paille", "Le verre fait miroir", "La paille gonfle dans l’eau"], e: "🥤👀", f: "C’est la réfraction : la lumière est déviée en passant de l’eau à l’air, car elle n’y va pas à la même vitesse." },
  { l: 3, q: "Quelle est l’unité de force dans le Système international ?", a: ["Le newton", "Le joule", "Le watt", "Le pascal"], e: "💪📏", f: "Un newton, c’est à peu près la force exercée par une petite pomme de 100 g posée dans ta main." },
  { l: 3, q: "Dans le vide, on lâche en même temps une plume et une boule de bowling. Que se passe-t-il ?", a: ["Elles arrivent en même temps", "La boule arrive bien avant", "La plume arrive avant", "La plume flotte sur place"], e: "🎳⬇️", f: "Un astronaute d’Apollo 15 l’a vérifié sur la Lune en 1971, avec un marteau et une plume de faucon !" },
  { l: 3, q: "Que fait un objet en mouvement si aucune force ne s’exerce sur lui ?", a: ["Il garde sa vitesse, en ligne droite", "Il ralentit puis s’arrête", "Il accélère sans fin", "Il tourne en rond"], e: "🛷🧊", f: "C’est le principe d’inertie. Sur Terre, les objets finissent par s’arrêter à cause des frottements." },
  { l: 3, q: "Quelle grandeur se mesure en kilogrammes dans le Système international ?", a: ["La masse", "Le poids", "La force", "La densité"], e: "⚖️🤔", f: "Le poids est une force, mesurée en newtons : sur la Lune, ton poids diminue, mais ta masse reste la même." },
  { l: 3, q: "Pourquoi un couteau bien aiguisé coupe-t-il mieux ?", a: ["La pression exercée est plus grande", "Il est plus lourd", "Il est plus froid", "Il frotte davantage"], e: "🔪🥕", f: "Même force, surface plus petite : pression plus grande. Les raquettes à neige font l’inverse pour ne pas s’enfoncer !" },
  { l: 3, q: "Pourquoi un énorme paquebot en acier flotte-t-il ?", a: ["Il déplace un grand volume d’eau", "L’acier est plus léger que l’eau", "Ses moteurs le soulèvent", "Sa coque est remplie d’hélium"], e: "🚢🌊", f: "C’est la poussée d’Archimède : un objet flotte si l’eau qu’il déplace pèse autant que lui." },
  { l: 3, q: "Quel élément chimique a pour symbole « Au » ?", a: ["L’or", "L’argent", "L’aluminium", "Le cuivre"], e: "🧪❓", f: "« Au » vient du latin « aurum », qui veut dire « or ». L’argent, lui, s’écrit Ag, de « argentum »." },
  { l: 3, q: "Quel est le premier élément du tableau périodique ?", a: ["L’hydrogène", "L’hélium", "L’oxygène", "Le carbone"], e: "📋🔬", f: "C’est l’élément le plus léger et le plus abondant de l’Univers." },
  { l: 3, q: "À quel savant attribue-t-on la phrase « Rien ne se perd, rien ne se crée, tout se transforme » ?", a: ["Antoine Lavoisier", "Louis Pasteur", "Blaise Pascal", "René Descartes"], e: "⚗️⚖️", f: "Lavoisier a montré qu’au cours d’une réaction chimique, la masse totale reste la même." },
  { l: 3, q: "Que produit la combustion complète du méthane (le gaz de cuisine) ?", a: ["Du CO₂ et de l’eau", "De l’oxygène et de l’azote", "Du carbone et de l’hydrogène", "De l’ozone et du sel"], e: "🔥🍳", f: "Une flamme bleue indique une bonne combustion ; une flamme jaune peut produire du monoxyde de carbone, très toxique." },
  { l: 3, q: "Quel est le pH de l’eau pure à 25 °C ?", a: ["7", "0", "14", "1"], e: "💧🧪", f: "En dessous de 7, une solution est acide ; au-dessus, elle est basique. L’eau pure est neutre." },
  { l: 3, q: "Quelle est la charge électrique d’un électron ?", a: ["Négative", "Positive", "Nulle", "Variable"], e: "⚛️⚡", f: "Le proton est positif et le neutron, comme son nom l’indique, est électriquement neutre." },
  { l: 3, q: "Quelle loi relie la tension, la résistance et l’intensité : U = R × I ?", a: ["La loi d’Ohm", "La loi de Newton", "La loi de Joule", "La loi de Coulomb"], e: "🔌📐", f: "Georg Ohm l’a publiée en 1827. L’unité de résistance, l’ohm (Ω), porte son nom." },
  { l: 3, q: "En quelle unité exprime-t-on la puissance d’un appareil électrique ?", a: ["Le watt", "Le volt", "L’ampère", "L’ohm"], e: "💡🔌", f: "Le watt doit son nom à James Watt, qui a perfectionné la machine à vapeur au XVIIIe siècle." },
  { l: 3, q: "Dans une centrale nucléaire, quelle réaction produit la chaleur ?", a: ["La fission de noyaux d’uranium", "La fusion de l’hydrogène", "La combustion du charbon", "L’électrolyse de l’eau"], e: "⚛️🏭", f: "La chaleur fait bouillir de l’eau ; la vapeur fait tourner une turbine reliée à un alternateur." },
  { l: 3, q: "Comment s’appelle l’énergie que possède un objet en mouvement ?", a: ["L’énergie cinétique", "L’énergie potentielle", "L’énergie chimique", "L’énergie nucléaire"], e: "🎢⚡", f: "Elle dépend du carré de la vitesse : rouler deux fois plus vite, c’est avoir quatre fois plus d’énergie !" },
  { l: 3, q: "Quel est le seul nombre premier pair ?", a: ["2", "0", "4", "1"], e: "🔢🤔", f: "Tous les autres nombres pairs sont divisibles par 2, donc ils ne peuvent pas être premiers. Et 1 n’est pas premier !" },
  { l: 3, q: "Un triangle rectangle a deux côtés de 3 cm et 4 cm autour de l’angle droit. Combien mesure l’hypoténuse ?", a: ["5 cm", "6 cm", "7 cm", "12 cm"], e: "📐✏️", f: "3² + 4² = 9 + 16 = 25 = 5². C’est le théorème de Pythagore !" },
  { l: 3, q: "Le nombre π est le rapport entre le périmètre d’un cercle et…", a: ["Son diamètre", "Son rayon", "Son aire", "Son centre"], e: "⭕📏", f: "π vaut environ 3,14159… Ses décimales continuent à l’infini, sans jamais former de motif qui se répète." },
  { l: 3, q: "Combien vaut 2 puissance 10 ?", a: ["1 024", "1 000", "20", "512"], e: "💻🔢", f: "C’est pour ça qu’en informatique, un kilooctet a longtemps désigné 1 024 octets plutôt que 1 000." },
  { l: 3, q: "On lance trois fois une pièce équilibrée. Quelle est la probabilité d’obtenir trois fois « pile » ?", a: ["1 chance sur 8", "1 chance sur 3", "1 chance sur 6", "1 chance sur 2"], e: "🎲🤞", f: "½ × ½ × ½ = ⅛. Et la pièce n’a pas de mémoire : chaque lancer est indépendant des autres !" },
  { l: 3, q: "Combien de litres contient un mètre cube ?", a: ["1 000", "100", "10", "10 000"], e: "📦💧", f: "Une piscine olympique contient au moins 2 500 mètres cubes, soit 2,5 millions de litres d’eau !" },
  { l: 3, q: "Quel scientifique a découvert la pénicilline en 1928 ?", a: ["Alexander Fleming", "Louis Pasteur", "Robert Koch", "Edward Jenner"], e: "🧫💊", f: "Il l’a découverte un peu par hasard : une moisissure avait poussé dans une boîte de culture de bactéries oubliée." },
  { l: 3, q: "Combien de bits y a-t-il dans un octet ?", a: ["8", "2", "10", "16"], e: "💾🔢", f: "Avec 8 bits, on peut coder 256 valeurs différentes, de 0 à 255." },
  { l: 3, q: "Comment appelle-t-on la méthode où une IA apprend à partir de très nombreux exemples ?", a: ["L’apprentissage automatique", "La programmation manuelle", "La compression de données", "Le chiffrement"], e: "🤖📚", f: "En anglais, on dit « machine learning ». C’est ainsi qu’une IA apprend à reconnaître des images ou des voix." },
  { l: 3, q: "Malgré le film « Jurassic Park », à quelle période vivait le tyrannosaure ?", a: ["Le Crétacé", "Le Jurassique", "Le Trias", "Le Permien"], e: "🦖⏳", f: "Le T. rex a vécu à la toute fin du Crétacé, il y a environ 68 à 66 millions d’années." },
  { l: 3, q: "Lequel de ces animaux préhistoriques n’était PAS un dinosaure ?", a: ["Le ptéranodon", "Le tyrannosaure", "Le stégosaure", "L’iguanodon"], e: "🦴🔍", f: "Les ptérosaures volants étaient des cousins des dinosaures, mais pas des dinosaures, tout comme les grands reptiles marins de l’époque." },
  { l: 3, q: "Quelle vitamine notre peau fabrique-t-elle grâce au soleil ?", a: ["La vitamine D", "La vitamine C", "La vitamine A", "La vitamine B12"], e: "☀️🧍", f: "La vitamine D aide le corps à fixer le calcium dans les os." },
  { l: 3, q: "Quelle maladie, due à un manque de vitamine C, touchait les marins d’autrefois ?", a: ["Le scorbut", "La peste", "La rage", "Le paludisme"], e: "⛵🍋", f: "Les marins britanniques emportaient du jus de citron vert pour s’en protéger, d’où leur surnom de « limeys »." },
  { l: 3, q: "Pendant quelle phase du sommeil fait-on les rêves les plus vifs ?", a: ["Le sommeil paradoxal", "Le sommeil lent léger", "L’endormissement", "Le sommeil lent profond"], e: "😴💭", f: "On le dit « paradoxal » car le cerveau est très actif alors que les muscles sont presque paralysés." },
  { l: 3, q: "Lequel de ces microbes n’est pas une cellule et ne peut pas se multiplier seul ?", a: ["Le virus", "La bactérie", "La levure", "L’amibe"], e: "🦠🔬", f: "Un virus doit entrer dans une cellule et utiliser sa machinerie pour fabriquer des copies de lui-même." },
  { l: 3, q: "Quel savant américain a inventé le paratonnerre au XVIIIe siècle ?", a: ["Benjamin Franklin", "Thomas Edison", "Nikola Tesla", "Alessandro Volta"], e: "⚡🏠", f: "Franklin étudiait l’électricité des orages. On raconte qu’en 1752, il a fait voler un cerf-volant sous l’orage pour le prouver." },
  { l: 3, q: "Comment s’appelle le passage direct de l’état solide à l’état gazeux ?", a: ["La sublimation", "La fusion", "La condensation", "La vaporisation"], e: "🧊💨", f: "La glace carbonique (du CO₂ solide) se sublime à −78 °C : elle « fume » sans jamais devenir liquide." },
  { l: 3, q: "Combien de zéros compte un milliard ?", a: ["9", "6", "12", "10"], e: "🔢💰", f: "Attention : le « billion » anglais vaut un milliard, alors qu’en français un billion vaut mille milliards !" },
  { l: 3, q: "Quel savant a énoncé la loi de la gravitation universelle en 1687 ?", a: ["Isaac Newton", "Galilée", "Albert Einstein", "Johannes Kepler"], e: "🌍⬇️", f: "Il a montré que la même force fait tomber les objets sur Terre et maintient la Lune en orbite." },
  { l: 3, q: "Où sont fabriqués les globules rouges chez l’adulte ?", a: ["Dans la moelle osseuse", "Dans le cœur", "Dans l’estomac", "Dans les reins"], e: "🩸🏭", f: "La moelle osseuse produit environ 2 millions de globules rouges… chaque seconde !" },

  // ===== Niveau 4 : Adultes =====
  { l: 4, q: "Quel groupe sanguin est surnommé « donneur universel » pour les globules rouges ?", a: ["O négatif", "AB positif", "A positif", "B négatif"], e: "🩸💉", f: "À l’inverse, les personnes AB positif peuvent recevoir les globules rouges de tous les groupes : ce sont les « receveurs universels »." },
  { l: 4, q: "Qui est souvent considérée comme la première programmeuse de l’histoire ?", a: ["Ada Lovelace", "Grace Hopper", "Hedy Lamarr", "Marie Curie"], e: "💻📜", f: "En 1843, elle publie un algorithme destiné à la « machine analytique » de Charles Babbage, qui ne fut jamais construite." },
  { l: 4, q: "Qui a imaginé le World Wide Web en 1989, au CERN ?", a: ["Tim Berners-Lee", "Bill Gates", "Steve Jobs", "Vinton Cerf"], e: "🌐💻", f: "Il voulait aider les chercheurs à partager leurs documents. Le Web n’est qu’un des services d’Internet, qui existait avant lui." },
  { l: 4, q: "À quelle température correspond le zéro absolu ?", a: ["−273,15 °C", "−100 °C", "−459,67 °C", "−373,15 °C"], e: "🥶🌡️", f: "C’est 0 kelvin, la température la plus basse possible : l’agitation des atomes y serait minimale." },
  { l: 4, q: "Quel chimiste a publié en 1869 sa célèbre classification périodique des éléments ?", a: ["Dmitri Mendeleïev", "Antoine Lavoisier", "John Dalton", "Niels Bohr"], e: "📋⚗️", f: "Il avait laissé des cases vides pour des éléments inconnus, dont il prédisait les propriétés. On les a découverts ensuite !" },
  { l: 4, q: "À quelle ère géologique vivaient les dinosaures non aviens ?", a: ["Le Mésozoïque", "Le Paléozoïque", "Le Cénozoïque", "Le Précambrien"], e: "🦕⏳", f: "Le Mésozoïque se divise en trois périodes : le Trias, le Jurassique et le Crétacé." },
  { l: 4, q: "Un ballon de foot classique compte 12 pentagones. Combien a-t-il d’hexagones ?", a: ["20", "12", "24", "32"], e: "⚽📐", f: "Cette forme est un icosaèdre tronqué : 32 faces en tout, comme le ballon Telstar de la Coupe du monde 1970." },
  { l: 4, q: "Quel savant grec a estimé la circonférence de la Terre au IIIe siècle av. J.-C. ?", a: ["Ératosthène", "Archimède", "Pythagore", "Euclide"], e: "🌍📐", f: "Il a comparé les ombres à midi, le même jour, à Syène et à Alexandrie, en Égypte. Son résultat était assez proche de la réalité." },
  { l: 4, q: "Quel organe produit la bile ?", a: ["Le foie", "La vésicule biliaire", "Le pancréas", "L’estomac"], e: "🍟🔬", f: "La vésicule biliaire ne fait que la stocker. La bile aide à digérer les graisses." },
  { l: 4, q: "Quel mathématicien a joué un rôle clé pour casser le code Enigma pendant la Seconde Guerre mondiale ?", a: ["Alan Turing", "John von Neumann", "Claude Shannon", "Charles Babbage"], e: "🔐📻", f: "C’est aussi un pionnier de l’informatique : sa « machine de Turing » est un modèle théorique de l’ordinateur." },
  { l: 4, q: "Quel est l’élément chimique le plus abondant dans la croûte terrestre ?", a: ["L’oxygène", "Le silicium", "Le fer", "L’aluminium"], e: "🌍🧪", f: "Il représente près de la moitié de la masse de la croûte, combiné aux autres éléments dans les roches." },
  { l: 4, q: "Quel métal est liquide à 20 °C ?", a: ["Le mercure", "Le gallium", "Le plomb", "L’étain"], e: "🌡️🥄", f: "Le mercure fond à −39 °C. Son symbole, Hg, vient de « hydrargyrum », qui signifie « argent liquide »." },
  { l: 4, q: "Quelle particule, prédite en 1964, a été observée au CERN en 2012 ?", a: ["Le boson de Higgs", "Le neutrino", "Le positron", "Le quark top"], e: "⚛️🔬", f: "Elle explique pourquoi certaines particules ont une masse. Peter Higgs et François Englert ont reçu le Nobel en 2013." },
  { l: 4, q: "Qui a découvert l’électron, en 1897 ?", a: ["Joseph John Thomson", "Ernest Rutherford", "Niels Bohr", "Max Planck"], e: "⚛️🔍", f: "Thomson imaginait l’atome comme un « pudding aux raisins », avant que Rutherford ne découvre le noyau en 1911." },
  { l: 4, q: "Qui a découvert la radioactivité en 1896 ?", a: ["Henri Becquerel", "Marie Curie", "Pierre Curie", "Ernest Rutherford"], e: "☢️🔬", f: "Un peu par hasard : des sels d’uranium avaient voilé une plaque photographique rangée dans un tiroir." },
  { l: 4, q: "Quels éléments Marie et Pierre Curie ont-ils découverts en 1898 ?", a: ["Le polonium et le radium", "L’uranium et le thorium", "Le radon et le césium", "Le plutonium et le radium"], e: "☢️⚗️", f: "Le polonium a été nommé en l’honneur de la Pologne, pays natal de Marie Curie." },
  { l: 4, q: "Quelle théorie Pasteur a-t-il réfutée grâce à ses ballons à col de cygne ?", a: ["La génération spontanée", "La théorie des germes", "L’évolution des espèces", "La circulation du sang"], e: "⚗️🦢", f: "Ses bouillons stérilisés restaient intacts tant que les poussières de l’air ne pouvaient pas les atteindre." },
  { l: 4, q: "Quel naturaliste a publié « De l’origine des espèces » en 1859 ?", a: ["Charles Darwin", "Jean-Baptiste Lamarck", "Gregor Mendel", "Carl von Linné"], e: "📖🐢", f: "Son voyage de cinq ans autour du monde à bord du Beagle, notamment aux Galápagos, a nourri sa théorie." },
  { l: 4, q: "Avec quelles plantes Gregor Mendel a-t-il découvert les lois de l’hérédité ?", a: ["Des petits pois", "Des tulipes", "Du blé", "Des haricots"], e: "🧬🌱", f: "Ses travaux, publiés en 1866, sont restés presque ignorés jusqu’à leur redécouverte en 1900." },
  { l: 4, q: "Laquelle de ces bases azotées ne se trouve PAS dans l’ADN ?", a: ["L’uracile", "L’adénine", "La guanine", "La cytosine"], e: "🧬🔬", f: "L’uracile remplace la thymine dans l’ARN. Les 4 bases de l’ADN sont A, T, G et C." },
  { l: 4, q: "Combien de gènes codant des protéines compte environ le génome humain ?", a: ["Environ 20 000", "Environ 2 000", "Environ 200 000", "Environ 2 millions"], e: "🧬📚", f: "Bien moins que prévu ! Avant le séquençage du génome, achevé en 2003, on en imaginait souvent plus de 100 000." },
  { l: 4, q: "Combien de paires de côtes possède un être humain, en général ?", a: ["12", "10", "14", "24"], e: "🦴🧍", f: "Hommes et femmes en ont autant : l’idée que les hommes auraient une côte en moins est une légende." },
  { l: 4, q: "Pourquoi le daltonisme touche-t-il surtout les hommes ?", a: ["Le gène est sur le chromosome X", "Les hommes ont moins de cônes", "Il est lié au chromosome Y", "La testostérone abîme la rétine"], e: "👁️🧬", f: "N’ayant qu’un chromosome X, un homme est atteint dès que celui-ci porte le gène. Environ 8 % des hommes européens sont concernés." },
  { l: 4, q: "Lors de la « guerre des courants », quel type de courant défendait Nikola Tesla ?", a: ["Le courant alternatif", "Le courant continu", "Le courant électrostatique", "Le courant magnétique"], e: "⚡🥊", f: "Edison défendait le courant continu. C’est l’alternatif qui l’a emporté, car il se transporte mieux sur de longues distances." },
  { l: 4, q: "Quel physicien a imaginé un chat à la fois mort et vivant pour illustrer la physique quantique ?", a: ["Erwin Schrödinger", "Werner Heisenberg", "Niels Bohr", "Max Planck"], e: "🐈📦", f: "En 1935, il voulait montrer l’absurdité d’appliquer certaines idées quantiques aux objets de notre échelle." },
  { l: 4, q: "En 1791, le mètre a été défini comme le dix-millionième de quelle longueur ?", a: ["Un quart de méridien terrestre", "La circonférence de l’équateur", "Le diamètre de la Terre", "La distance Paris–Marseille"], e: "📏🌍", f: "Delambre et Méchain ont mesuré l’arc de méridien entre Dunkerque et Barcelone pour en fixer la longueur." },
  { l: 4, q: "Combien vaut 0! (factorielle de zéro) ?", a: ["1", "0", "L’infini", "Elle n’est pas définie"], e: "❗🔢", f: "Par convention, 0! = 1 : il existe exactement une façon de ranger zéro objet." },
  { l: 4, q: "Quelle est la valeur approchée du nombre d’or ?", a: ["1,618", "3,1416", "2,718", "1,414"], e: "🎨📐", f: "Il vaut (1 + √5) / 2. Le rapport entre deux termes consécutifs de la suite de Fibonacci s’en approche." },
  { l: 4, q: "Combien existe-t-il de nombres premiers ?", a: ["Une infinité", "168", "Environ un million", "Exactement 1 000"], e: "🔢🤔", f: "Euclide l’a démontré il y a environ 2 300 ans, avec une preuve encore enseignée aujourd’hui." },
  { l: 4, q: "Quel célèbre théorème, resté sans preuve pendant plus de 350 ans, a été démontré par Andrew Wiles en 1994 ?", a: ["Le dernier théorème de Fermat", "La conjecture de Poincaré", "L’hypothèse de Riemann", "La conjecture de Goldbach"], e: "📝🧠", f: "Fermat avait noté dans une marge avoir une preuve « merveilleuse »… que la marge était trop étroite pour contenir." },
  { l: 4, q: "Quel savant français a inventé une machine à calculer à seulement 19 ans ?", a: ["Blaise Pascal", "René Descartes", "Pierre de Fermat", "Denis Papin"], e: "🧮⚙️", f: "Il l’a conçue en 1642 pour aider son père, chargé de collecter les impôts. On l’appelle la Pascaline." },
  { l: 4, q: "De quoi est faite la « mine » d’un crayon à papier ?", a: ["De graphite et d’argile", "De plomb", "De charbon de bois", "D’étain"], e: "✏️🧪", f: "Malgré l’expression « mine de plomb », il n’y a pas de plomb : le graphite est une forme de carbone, comme le diamant." },
  { l: 4, q: "Quel physicien a découvert l’induction électromagnétique en 1831 ?", a: ["Michael Faraday", "André-Marie Ampère", "Alessandro Volta", "James Clerk Maxwell"], e: "🧲⚡", f: "C’est le principe des alternateurs : un aimant qui bouge près d’une bobine y crée un courant électrique." },
  { l: 4, q: "Quel phénomène rend la sirène d’une ambulance plus aiguë quand elle s’approche ?", a: ["L’effet Doppler", "L’effet Joule", "L’effet de serre", "L’effet papillon"], e: "🚑🔊", f: "Christian Doppler l’a décrit en 1842. Les radars routiers utilisent le même principe pour mesurer la vitesse." },
  { l: 4, q: "Quel écrivain a formulé les « trois lois de la robotique » ?", a: ["Isaac Asimov", "Jules Verne", "Philip K. Dick", "Arthur C. Clarke"], e: "🤖📜", f: "Il les a énoncées en 1942 dans une nouvelle. C’est aussi lui qui a popularisé le mot « robotique »." },
  { l: 4, q: "Quel ordinateur d’IBM a battu le champion du monde d’échecs Garry Kasparov en 1997 ?", a: ["Deep Blue", "AlphaGo", "Watson", "Deep Thought"], e: "♟️🤖", f: "Il pouvait évaluer environ 200 millions de positions par seconde." },
  { l: 4, q: "Quel est le premier dinosaure à avoir reçu un nom scientifique, en 1824 ?", a: ["Le mégalosaure", "L’iguanodon", "Le tyrannosaure", "Le diplodocus"], e: "🦴📜", f: "Le mot « dinosaure » n’a été inventé qu’en 1842, par Richard Owen. Il signifie « lézard terrible »." },
  { l: 4, q: "Comment appelle-t-on les excréments fossilisés ?", a: ["Les coprolithes", "Les gastrolithes", "Les ichnites", "Les stromatolithes"], e: "🦕💩", f: "Ils renseignent sur l’alimentation des animaux disparus. Un coprolithe attribué à un T. rex mesure plus de 40 cm !" },
  { l: 4, q: "Quelle réaction le réacteur expérimental ITER, en Provence, cherche-t-il à maîtriser ?", a: ["La fusion nucléaire", "La fission nucléaire", "La combustion de l’hydrogène", "La photosynthèse artificielle"], e: "⚛️🔥", f: "Il s’agit de reproduire sur Terre la réaction qui fait briller les étoiles, en fusionnant des noyaux légers." },
  { l: 4, q: "Combien de joules vaut environ une calorie ?", a: ["4,18", "1 000", "0,5", "100"], e: "🍫🔥", f: "Attention : les « calories » des emballages alimentaires sont en fait des kilocalories, soit environ 4 184 joules !" },
  { l: 4, q: "Quel inventeur a breveté la dynamite en 1867 ?", a: ["Alfred Nobel", "Gustave Eiffel", "Thomas Edison", "Henri Becquerel"], e: "💥📜", f: "Sa fortune a servi à créer les prix Nobel, décernés pour la première fois en 1901." },
  { l: 4, q: "Quel médecin a montré, vers 1847, que le lavage des mains sauvait des vies à la maternité ?", a: ["Ignace Semmelweis", "Louis Pasteur", "Robert Koch", "Claude Bernard"], e: "🧼🏥", f: "À Vienne, le lavage des mains au chlore a fait chuter la mortalité des jeunes mères. Il fut pourtant moqué !" },
  { l: 4, q: "Qui a découvert les rayons X en 1895 ?", a: ["Wilhelm Röntgen", "Henri Becquerel", "Marie Curie", "Max Planck"], e: "🦴📸", f: "Une de ses premières radiographies montre la main de sa femme et sa bague. Il reçut le tout premier Nobel de physique, en 1901." },
  { l: 4, q: "Quel gaz est responsable de l’odeur d’œuf pourri ?", a: ["Le sulfure d’hydrogène", "Le méthane", "L’ammoniac", "Le dioxyde de carbone"], e: "🥚👃", f: "Le méthane du gaz de ville est inodore : on y ajoute un produit soufré malodorant pour détecter les fuites." },
  { l: 4, q: "Que fait un mélange d’eau et de fécule de maïs si on le frappe d’un coup sec ?", a: ["Il durcit comme un solide", "Il éclabousse comme de l’eau", "Il se met à bouillir", "Il devient transparent"], e: "🌽💧", f: "C’est un fluide non newtonien : sa viscosité augmente sous le choc. Dans une piscine remplie, on peut même courir dessus !" },
  { l: 4, q: "Comment appelle-t-on l’état de la matière présent dans les éclairs et les étoiles ?", a: ["Le plasma", "Le gel", "Le cristal liquide", "L’aérosol"], e: "⚡✨", f: "Dans un plasma, le gaz est si chaud ou si énergisé que ses atomes perdent des électrons." },
  { l: 4, q: "À quelle température l’eau liquide est-elle la plus dense ?", a: ["Vers 4 °C", "À 0 °C", "À 100 °C", "Vers 37 °C"], e: "💧⚖️", f: "C’est pourquoi, en hiver, l’eau du fond d’un lac profond reste vers 4 °C, sous la glace." },
  { l: 4, q: "Combien vaut la somme 1 + 2 + 3 + … + 100 ?", a: ["5 050", "5 000", "10 100", "4 950"], e: "➕🧠", f: "Enfant, Gauss l’aurait trouvée en un instant : 1 + 100, 2 + 99… font 50 paires de 101." },
  { l: 4, q: "Quel langage de programmation doit son nom à une troupe comique britannique ?", a: ["Python", "Java", "Ruby", "Pascal"], e: "💻😂", f: "Son créateur, Guido van Rossum, était fan des Monty Python. Le serpent du logo n’est venu qu’après !" },
  { l: 4, q: "Quel insecte, retrouvé en 1947 dans un ordinateur, a popularisé le mot « bug » ?", a: ["Un papillon de nuit", "Une fourmi", "Un cafard", "Une mouche"], e: "💻🔍", f: "L’équipe de Grace Hopper l’a collé dans son cahier avec la mention « premier vrai cas de bug trouvé ». Le mot existait déjà !" },
]);
